import warnings; warnings.filterwarnings("ignore")
import numpy as np
import pandas as pd
from scipy.optimize import minimize
from sklearn.model_selection import KFold
from sklearn.preprocessing import StandardScaler
from sklearn.gaussian_process import GaussianProcessRegressor
from sklearn.gaussian_process.kernels import ConstantKernel, Matern, WhiteKernel
from sklearn.metrics import r2_score,mean_absolute_error
train=pd.read_csv("/work/b3_htsteel_pareto_train.csv"); pool=pd.read_csv("/work/b3_htsteel_pareto_pool.csv"); X=train.iloc[:,:-2].copy(); y=train.iloc[:,-2:].values; P=pool[X.columns].copy(); ids=pool.candidate_id.values
for col in X:
 if "duration" in col or "cooling" in col: X[col]=np.log1p(X[col]); P[col]=np.log1p(P[col])
X=X.drop(columns=["Fe","Heat treatment step 3 cooling rate"]); P=P[X.columns]
def optimizer(obj,theta,bounds):
 res=minimize(obj,theta,jac=True,bounds=bounds,method="L-BFGS-B",options={"maxiter":180,"ftol":1e-7}); return res.x,res.fun
folds=list(KFold(n_splits=5,shuffle=True,random_state=2026).split(X)); oof=np.zeros_like(y); pred=np.zeros((100,2)); fp=[]
for k,(a,b) in enumerate(folds+[(np.arange(len(X)),np.array([],dtype=int))]):
 scale=StandardScaler().fit(X.iloc[a]); xx=scale.transform(X.iloc[a]); pp=scale.transform(P); f=np.zeros((100,2))
 for j in range(2):
  kernel=ConstantKernel(1.,(.01,100))*Matern(np.ones(X.shape[1])*4,(.1,1000),nu=1.5)+WhiteKernel(.1,(.001,1.))
  gp=GaussianProcessRegressor(kernel=kernel,normalize_y=True,optimizer=optimizer,n_restarts_optimizer=0,random_state=42)
  gp.fit(xx,y[a,j]); f[:,j]=gp.predict(pp)
  if len(b): oof[b,j]=gp.predict(scale.transform(X.iloc[b]))
  else:
   pred[:,j],sd=gp.predict(pp,return_std=True); print("LENGTHS",j,sorted(zip(X.columns,gp.kernel_.k1.k2.length_scale),key=lambda t:t[1])); print("KERNEL",gp.kernel_)
 print("Finished fold",k)
 if len(b): fp.append(f)
print("ARD GP CV",r2_score(y,oof,multioutput="raw_values"),mean_absolute_error(y,oof,multioutput="raw_values"))
print(pd.DataFrame(pred,index=ids,columns=["yield","elong"]).round(2).to_string())
for ref in [np.array([0.,0.]),np.array([177.,5.])]:
 a=np.maximum(pred-ref,0); front=np.array([not np.any(np.all(a>=b,axis=1)&np.any(a>b,axis=1)) for b in a]); ix=np.where(front)[0]; ix=ix[np.argsort(-a[ix,0])]; a=a[ix]; n=len(a); k=min(5,n); dp=np.full((k+1,n),-np.inf); prev=np.full((k+1,n),-1,dtype=int); dp[1]=a[:,0]*a[:,1]
 for t in range(2,k+1):
  for i in range(t-1,n):
   vals=dp[t-1,:i]+a[i,0]*(a[i,1]-a[:i,1]); j=np.argmax(vals); dp[t,i]=vals[j]; prev[t,i]=j
 i=np.argmax(dp[k]); val=dp[k,i]; chosen=[]
 for t in range(k,0,-1): chosen.append(ix[i]); i=prev[t,i]
 print("GP OPT",ref,ids[chosen],val)
'

